// Package schema holds the Zotero item schema as plain Go data: item types,
// ordered fields per type, base-field mappings, creator types and the schema
// version in which each field first appeared.
//
// Default returns tables generated by cmd/schemagen. They contain facts only
// (names and ordering), no localized strings or descriptive text. Load parses
// a schema.json at runtime for operators who want a newer schema than the one
// compiled in; fields loaded that way report FieldIntroduced of 0.
//
// The package has no dependency on the parent zotero package, which is what
// lets zotero.MarshalItemData accept a *Schema without an import cycle.
package schema

//go:generate go run ../cmd/schemagen -commit b86c79b56479cadac3288e1f122cf34ef04e8809 -out schema_gen.go
